<script setup lang="ts">
import { ref,reactive,computed,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { get,post } from '../api/client'
import type { Design,Profile,Model,Page } from '../api/types'
import { allowed,session } from '../composables/session'
import { useQuery } from '../composables/useQuery'
import { useMutation } from '../composables/useMutation'
import { useDirty } from '../composables/useDirty'
import { date,short } from '../api/format'
import PageHeader from '../components/PageHeader.vue'
import Icon from '../components/Icon.vue'
import Feedback from '../components/Feedback.vue'
import JsonView from '../components/JsonView.vue'
import StatusBadge from '../components/StatusBadge.vue'
import EmptyState from '../components/EmptyState.vue'
import ResourceTable from '../components/ResourceTable.vue'
const route=useRoute(),router=useRouter(),versionId=String(route.params.versionId),pid=session.project!.id,root=`/projects/${pid}`,op=useMutation(),dirty=useDirty()
const design=useQuery(s=>get<Design>(`/api/v1/versions/${versionId}/design`,s),[],5000)
const profiles=useQuery(s=>get<Page<Profile>>(`/api/v1/projects/${pid}/metadata-profiles?limit=100`,s))
const prompt=ref(''),source=ref<string[]>([]),target=ref(''),tab=ref('plan'),agentId=ref(typeof route.query.agent==='string'?route.query.agent:''),answers=reactive<Record<string,string>>({})
const agent=useQuery<Model<'AgentRunResponse'>|null>(s=>agentId.value?get(`/api/v1/agent-runs/${agentId.value}`,s):Promise.resolve({data:null,etag:null,requestId:''}),[agentId],4000)
const clarifications=useQuery<Page<Model<'ClarificationResponse'>>|null>(s=>agentId.value?get(`/api/v1/agent-runs/${agentId.value}/clarifications`,s):Promise.resolve({data:null,etag:null,requestId:''}),[agentId],4000)
const canGenerate=computed(()=>!!design.data.value&&allowed('generate',design.data.value.available_actions||[]))
const plan=computed(()=>design.data.value?.etl_plan)
watch(()=>agent.data.value?.status,()=>void design.refresh())
async function generate(){design.invalidate();const r=await op.run(()=>post<Model<'AgentRunResponse'>>(`/api/v1/versions/${versionId}/generation`,{prompt:prompt.value,source_profile_ids:source.value,target_profile_id:target.value,provider:'deepseek'},{etag:design.etag.value}),'生成已受理，工作流将保存在服务端。');if(r){dirty.value=false;agentId.value=r.data.id;await router.replace({query:{...route.query,agent:r.data.id}});await design.refresh()}}
async function answer(){const pending=clarifications.data.value?.items.filter(q=>q.answer===null)||[];const r=await op.run(()=>post(`/api/v1/agent-runs/${agentId.value}/answers`,{answers:pending.map(q=>({question_key:q.question_key,answer:answers[q.question_key]||''}))}),'澄清回答已受理，继续原工作流。');if(r){dirty.value=false;await clarifications.refresh();await agent.refresh()}}
async function trial(){design.invalidate();await op.run(()=>post(`/api/v1/versions/${versionId}/trials`,{version_id:versionId,mode:'static',preparation_id:null}),'静态校验完成；这不代表真实引擎试运行成功。');await design.refresh()}
</script>
<template><PageHeader eyebrow="FROM INTENT TO DESIGN" title="Pipeline Studio" description="描述你的集成需求，与 AI 一起构建可审查的数据方案。"><span class="badge neutral">版本 {{design.data.value?.version.version_number||'—'}}</span><RouterLink :to="`${root}/versions/${versionId}`" class="button"><Icon name="shield" :size="15"/>版本审查与准备</RouterLink></PageHeader><Feedback :error="design.error.value" :loading="design.loading.value" @retry="design.refresh()"/><div class="studio-grid"><aside class="card studio-side"><div class="eyebrow">DESIGN BRIEF</div><h2>集成需求</h2><form @submit.prevent="generate" @input="dirty=true"><label class="field">使用受管模型<input :value="'DeepSeek · '+(agent.data.value?.provider_binding.model||'deepseek-v4.1-flash')" readonly/></label><fieldset style="border:0;padding:0;margin:0 0 20px"><legend class="field">源 Profile（至少一项）</legend><Feedback :error="profiles.error.value"/><label v-for="p in profiles.data.value?.items||[]" :key="p.id" class="profile-check"><input v-model="source" name="source" type="checkbox" :value="p.id" :disabled="!canGenerate"/><span>{{p.resource_name}}<small class="muted"> · {{short(p.id,6)}}</small></span></label><p v-if="!profiles.data.value?.items.length" class="subtle-label" style="margin-top:12px">请先到数据资产页完成只读探查。</p><small v-if="profiles.data.value?.has_more" class="muted">当前显示前100项。更多资源需通过资产目录定位。</small></fieldset><label class="field">目标 Profile<select v-model="target" name="target" required :disabled="!canGenerate"><option value="">选择已有目标结构</option><option v-for="p in profiles.data.value?.items||[]" :key="p.id" :value="p.id">{{p.resource_name}}</option></select></label><label class="field">用自然语言描述需求<textarea v-model="prompt" name="prompt" required rows="7" :disabled="!canGenerate" placeholder="例如：将订单数据同步到分析库，统一时间字段，并检查订单金额…"/></label><button class="button primary" :disabled="!canGenerate||!source.length||!target||op.busy.value||op.unknown.value"><Icon name="spark" :size="16"/>{{op.busy.value?'正在受理…':'生成集成方案'}}</button></form><p class="block-note">不向模型提供数据源密码。实际执行必须经过版本冻结、准备与独立审批。</p></aside><div class="stack"><section v-if="agent.data.value" class="card"><div class="card-heading"><div><h2>Agent 工作流</h2><p>独立于实际运行 · {{short(agent.data.value.id,12)}}</p></div><StatusBadge :value="agent.data.value.status"/></div><div class="card-body"><div class="steps"><span class="current">步骤 {{agent.data.value.step_count}}</span><span>自动修复 {{agent.data.value.repair_count}} / 3</span><span>服务端持久化</span></div><p v-if="agent.data.value.error_message" class="feedback error">{{agent.data.value.error_message}}</p><form v-if="agent.data.value.status==='waiting_input'" class="form-stack" @submit.prevent="answer" @input="dirty=true"><label v-for="q in clarifications.data.value?.items.filter(q=>q.answer===null)||[]" :key="q.id" class="field">{{q.question}}<textarea v-model="answers[q.question_key]" required/></label><button class="button primary" :disabled="op.busy.value||op.unknown.value">提交回答并恢复工作流</button></form></div></section><Feedback :error="op.error.value||agent.error.value" :notice="op.notice.value" :unknown="op.unknown.value"/><section class="card"><div class="card-heading"><div><h2>方案工作区</h2><p>{{design.data.value?.version.is_immutable?'已冻结 · 保留原始制品':'候选版本 · 只读审查'}}</p></div><button class="button small" :disabled="!plan||op.busy.value" @click="trial"><Icon name="code" :size="14"/>静态试算</button></div><div class="card-body"><div class="tabs" role="tablist"><button v-for="t in [['plan','方案'],['mapping','字段映射'],['dag','数据流'],['hocon','HOCON'],['quality','质量契约']]" :key="t[0]" :class="{selected:tab===t[0]}" role="tab" :aria-selected="tab===t[0]" @click="tab=t[0]!">{{t[1]}}</button></div><template v-if="plan"><JsonView v-if="tab==='plan'" :value="plan"/><ResourceTable v-if="tab==='mapping'" :rows="plan.field_mappings" :columns="[{key:'target_field',label:'目标字段'},{key:'source_fields',label:'来源字段'},{key:'expression',label:'映射表达式'},{key:'target_type',label:'目标类型'}]"/><div v-if="tab==='dag'" class="dag-view"><div class="dag-nodes"><div v-for="node in plan.nodes" :key="node.node_id" class="dag-node"><Icon :name="node.kind==='source'?'database':node.kind==='sink'?'layers':'flow'" :size="22"/><strong>{{node.node_id}}</strong><small>{{node.kind}} · {{node.resource_ref}}</small></div></div><div class="section-space"><h3>节点关系</h3><p v-for="(edge,i) in plan.edges" :key="i" class="mono muted" style="margin-top:10px">{{edge.from_node_id}} → {{edge.to_node_id}}</p></div></div><JsonView v-if="tab==='hocon'" :value="design.data.value?.hocon_text" code/><JsonView v-if="tab==='quality'" :value="plan.quality_contract"/></template><EmptyState v-else icon="spark" title="你的方案，将从这里开始" description="选择源与目标 Profile，描述需求，生成后即可审查映射、数据流与质量规则。"/></div></section><section v-if="design.data.value?.validation_report" class="card"><div class="card-heading"><div><h2>确定性门禁</h2><p>规则版本 {{design.data.value.validation_report.rule_version}}</p></div><StatusBadge :value="design.data.value.validation_report.passed?'passed':'failed'"/></div><div class="card-body"><p v-if="!design.data.value.validation_report.issues?.length" class="form-info">本次校验未发现问题。冻结与执行前仍会由服务端复验。</p><div v-for="issue in design.data.value.validation_report.issues" :key="issue.code+issue.location" class="feedback error"><strong>{{issue.code}} · {{issue.location}}</strong><p>{{issue.message}}</p></div><small class="muted">{{date(design.data.value.validation_report.created_at)}} · 服务器校验事实</small></div></section></div></div></template>
